	INSERT INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('1', 'actor_image_front', 'Prompt ảnh diễn viên mặt trước', 'Prompt diễn viên mặt trước mặc định', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nchất lượng cao cấp điện ảnh {{ visual_style }} nhiếp ảnh chân dung, chân dung diễn viên chuyên nghiệp siêu chi tiết:\n {{ description }}\n\nHướng máy: mặt trước\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh nông kiểu điện ảnh, f/1.4 khẩu độ lớn, xóa nhòa nền tự nhiên rõ\n- phong cách nhiếp ảnh chân dung thương mại chuyên nghiệp + kết chất bộ phim đương đại\n- Biểu cảm tự nhiên sinh động, giàu tính kể chuyện và cảm giác nhập vai nhân vật\n- Bố cục xuất sắc, bố cục ba phần kinh điển hoặc bố cục tỷ lệ vàng\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if style == \"real_people_ancient\" -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '[\"description\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-17 06:38:57', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('2', 'actor_image_other', 'góc bên diễn viên/prompt ảnh góc sau diễn viên', 'Diễn viên góc không phải mặt trước', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nNhân vật nhất quán cao, giữ nguyên danh tính.chân dung cùng một người như Ảnh tham chiếu, 100% nhất quán danh tính, cấu trúc khuôn mặt giống, kiểu tóc giống, trang phục giống, trang điểm giống, cơ sở tuổi tác và biểu cảm giống.\nĐổi góc nhìn hoàn toàn sang: {{ view_angle }} , cùng một người nhìn từ góc này, phối cảnh và đường viền đúng, hướng đầu tự nhiên khớp với góc nhìn này, không có yếu tố mặt trước nào còn sót, khuôn mặt không méo\nTư thế diễn viên: ĐỨNG THẲNG, TƯ THẾ TRUNG LẬP\n {{ extra_details }}\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh nông kiểu điện ảnh, f/1.4 khẩu độ lớn, xóa nhòa nền tự nhiên rõ\n- phong cách nhiếp ảnh chân dung thương mại chuyên nghiệp + kết chất bộ phim đương đại\n- Biểu cảm tự nhiên sinh động, giàu tính kể chuyện và cảm giác nhập vai nhân vật\n- Bố cục xuất sắc, bố cục ba phần kinh điển hoặc bố cục tỷ lệ vàng\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if style == \"real_people_ancient\" -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '[\"view_angle\", \"extra_details\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('3', 'character_image_front', 'Prompt ảnh nhân vật mặt trước', 'Prompt ảnh nhân vật mặt trước', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nNhân vật nhất quán cao, giữ nguyên danh tính.chân dung cùng một người như Ảnh tham chiếu 1, 100% nhất quán danh tính, cấu trúc khuôn mặt giống, kiểu tóc giống, trang điểm giống, cơ sở tuổi tác và biểu cảm giống.Nếu Ảnh tham chiếu 2 tồn tại, dùng trang phục của Ảnh tham chiếu 2.\nTư thế diễn viên: ĐỨNG THẲNG, TƯ THẾ TRUNG LẬP\n {{ extra_details }}\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh nông kiểu điện ảnh, f/1.4 khẩu độ lớn, xóa nhòa nền tự nhiên rõ\n- phong cách nhiếp ảnh chân dung thương mại chuyên nghiệp + kết chất bộ phim đương đại\n- Biểu cảm tự nhiên sinh động, giàu tính kể chuyện và cảm giác nhập vai nhân vật\n- Bố cục xuất sắc, bố cục ba phần kinh điển hoặc bố cục tỷ lệ vàng\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if style == \"real_people_ancient\" -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '[\"extra_details\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-19 09:00:34', '2026-03-30 16:00:00', 0, 0);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('4', 'prop_image_front', 'Prompt ảnh đạo cụ', 'Cận cảnh đạo cụ chất lượng cao', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nchất lượng cao cấp điện ảnh {{ visual_style }} nhiếp ảnh sản phẩm / cận cảnh đạo cụ, kết cấu chân thực siêu chi tiết:\n {{ description }}\nHướng máy: {{ view }} , góc quay kinh điển cho sản phẩm/góc quay đạo cụ\n {{ extra_details }}\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh nông kiểu điện ảnh, f/1.4 hoặc f/2.8, xóa nhòa nền rõ\n- phong cách nhiếp ảnh sản phẩm thương mại chuyên nghiệp + kết chất đạo cụ điện ảnh đương đại\n- chất liệu chân thực rõ nét, phản xạ kim loại/kết cấu da/khúc xạ thủy tinh/sợi vải rõ ràng\n- Bố cục xuất sắc, bố cục ba phần kinh điển hoặc đối xứng/bố cục giữa tâm\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '[\"description\", \"view\", \"extra_details\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('5', 'scene_image_front', 'Prompt ảnh bối cảnh', 'Bối cảnh điện ảnh chất lượng cao', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nchất lượng cao cấp điện ảnh {{ visual_style }} bối cảnh điện ảnh, không khí môi trường siêu chi tiết:\n {{ description }}\nHướng máy: {{ view }}\nVị trí chủ thể khung hình: giữa khung hình\n {{ extra_details }}\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh kiểu điện ảnh, f/2.8～f/5.6, lớp thị giác phong phú\n- phong cách nhiếp ảnh bối cảnh điện ảnh chuyên nghiệp + kết chất phim đương đại\n- ánh sáng và bóng đổ chân thực, hướng nguồn sáng rõ ràng, hạt môi trường/sương mù/giọt mưa/quầng sáng tự nhiên\n- Bố cục xuất sắc, đường hướng dẫn, tầng lớp rõ ràng, ba lớp gần - giữa - xa rõ ràng\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '[\"description\", \"view\", \"extra_details\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('6', 'costume_image_front', 'Prompt ảnh trang phục', 'Diễn xuất trang phục chất lượng cao', 'Phong cách thị giác: {{ visual_style }}\nPhong cách hình ảnh: {{ style }}\n\nchất lượng cao cấp điện ảnh {{ visual_style }} cận cảnh trang phục / trình bày diện trang phục toàn thân, kết cấu vải siêu chi tiết:\n {{ description }}\nCách diện: diện trang phục toàn thân\n {{ extra_details }}\nYêu cầu hình ảnh:\n- Chi tiết cực cao, 8k, độ phân giải, độ sắc nét và kết cấu tối ưu\n- độ sâu trường ảnh nông hoặc vừa kiểu điện ảnh, f/1.8～f/4, làm nổi bật kết cấu vải\n- phong cách nhiếp ảnh thời trang / trang phục điện ảnh chuyên nghiệp + kết chất phim đương đại\n- kết cấu vải chân thực, đường may, cúc áo, phụ kiện kim loại, nếp nhăn, chi tiết sử dụng rõ ràng\n- Bố cục xuất sắc, trang phục là chủ thể khung hình hoặc chiếm 2/3 diện tích trở lên\n- Khớp hoàn hảo với {{ visual_style }} ngôn ngữ hình ảnh và {{ style }} không khí tổng thể, phong cách nhất quán cao\n\nĐề xuất tiêu cực (mạnh):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if visual_style == \"anime\" -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '[\"description\", \"extra_details\", \"visual_style\", \"style\", \"base_negative\"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
